full = {k:v for k,v in {
 'F3_Z01_temp':'Zone_F3_Z01.Zone_Air_Temperature_Sensor',
 'F2_Z01_temp':'Zone_F2_Z01.Zone_Air_Temperature_Sensor',
 'F3_Z02_temp':'Zone_F3_Z02.Zone_Air_Temperature_Sensor',
 'F3_Z03_temp':'Zone_F3_Z03.Zone_Air_Temperature_Sensor',
 'F3_Z05_temp':'Zone_F3_Z05.Zone_Air_Temperature_Sensor',
 'F4_Z01_temp':'Zone_F4_Z01.Zone_Air_Temperature_Sensor',
}.items()}
full = {k:idmap[v] for k,v in full.items()}
data={}
for row in csv.DictReader(open(VALUES_CSV)):
    if row['timeseries_id'] in full.values():
        data.setdefault(row['timeseries_id'],[]).append((row['timestamp'],float(row['value'])))
def monthly(tid):
    ds=sorted(data[tid])
    d={}
    for ts,v in ds:
        ym=ts[:7]
        d.setdefault(ym,[]).append(v)
    return {ym:sum(vs)/len(vs) for ym,vs in d.items()}
ms = {k:monthly(v) for k,v in full.items()}
months=sorted(ms['F3_Z01_temp'].keys())
print("month   F3Z01  F2Z01  F3Z02  F3Z03  F3Z05  F4Z01  delta(F3Z01 - avg others)")
for m in months:
    others=[ms['F2_Z01_temp'][m],ms['F3_Z02_temp'][m],ms['F3_Z03_temp'][m],ms['F3_Z05_temp'][m],ms['F4_Z01_temp'][m]]
    others=[x for x in others if x is not None]
    a=sum(others)/len(others) if others else float('nan')
    print(m, round(ms['F3_Z01_temp'][m],2), round(ms['F2_Z01_temp'][m],2), round(ms['F3_Z02_temp'][m],2), round(ms['F3_Z03_temp'][m],2), round(ms['F3_Z05_temp'][m],2), round(ms['F4_Z01_temp'][m],2), round(ms['F3_Z01_temp'][m]-a,2))
